package com.sami.app.sales.service;
import com.sami.app.common.exception.*; import com.sami.app.sales.domain.SaleStatus; import java.util.*;
public final class SaleLifecycle { private SaleLifecycle(){} private static final Map<SaleStatus,Set<SaleStatus>> ALLOWED=Map.of(SaleStatus.DRAFT,Set.of(SaleStatus.CONFIRMED,SaleStatus.CANCELLED),SaleStatus.CONFIRMED,Set.of(SaleStatus.COMPLETED,SaleStatus.CANCELLED),SaleStatus.COMPLETED,Set.of(SaleStatus.PARTIALLY_RETURNED,SaleStatus.RETURNED),SaleStatus.PARTIALLY_RETURNED,Set.of(SaleStatus.PARTIALLY_RETURNED,SaleStatus.RETURNED)); public static boolean allows(SaleStatus from,SaleStatus to){return ALLOWED.getOrDefault(from,Set.of()).contains(to);} public static void require(SaleStatus from,SaleStatus to){if(!allows(from,to))throw new ApiException(ErrorCode.OPERATION_NOT_ALLOWED,"Invalid sale transition: "+from+" -> "+to);} }
